import{_ as a,c as t,o as e,a4 as r}from"./chunks/framework.DzOtv0XR.js";const f=JSON.parse('{"title":"算法","description":"","frontmatter":{},"headers":[],"relativePath":"javascript/algorithms/index.md","filePath":"javascript/algorithms/index.md"}'),l={name:"javascript/algorithms/index.md"},i=r(`<h1 id="算法" tabindex="-1">算法 <a class="header-anchor" href="#算法" aria-label="Permalink to &quot;算法&quot;">​</a></h1><h2 id="算法方法-思想" tabindex="-1">算法方法/思想 <a class="header-anchor" href="#算法方法-思想" aria-label="Permalink to &quot;算法方法/思想&quot;">​</a></h2><h3 id="枚举" tabindex="-1">枚举 <a class="header-anchor" href="#枚举" aria-label="Permalink to &quot;枚举&quot;">​</a></h3><ul><li><p>合理设置尝试范围，减少不必要尝试。例：完美立方 四重循环</p></li><li><p>链表 -- 两个 next --&gt; 树 -- 节点指回 -&gt; 图</p></li><li><p>无单个子节点，完全二叉树</p></li><li><p>二叉搜索树，有序，空树，左子树(所有)，右子树(所有)，根结点，查找 O(n) =&gt; O(log(n))，退化 O(n)，只有一侧树 =》平衡</p></li></ul><p><a href="https://zhuanlan.zhihu.com/p/74584796" target="_blank" rel="noreferrer">优秀程序员都应该学习的数据结构与算法项目（GitHub 开源清单） - 知乎</a></p><ul><li><p>测试用例，单步验证</p><p>暴力解法</p><p>解题线索，解题模板</p></li></ul><p><a href="https://www.jianshu.com/p/8876704ea9c8" target="_blank" rel="noreferrer">LeetCode 算法题刷题心得（JavaScript） - 简书</a></p><h3 id="分治" tabindex="-1">分治 <a class="header-anchor" href="#分治" aria-label="Permalink to &quot;分治&quot;">​</a></h3><p>分解 -&gt; 解决（触底）-&gt; 合并（回溯）</p><p>比如归并排序，靠左右各自排序，再合并</p><p>二分查找:</p><ul><li><p>猜 1-1000 之间的一个数，猜多少次 <code>2 ** 10 = 1024</code></p><p>有序 比较中点 范围减半</p></li></ul><h3 id="贪心" tabindex="-1">贪心 <a class="header-anchor" href="#贪心" aria-label="Permalink to &quot;贪心&quot;">​</a></h3><p>每次操作局部最优，以达成全局最优</p><h3 id="回溯" tabindex="-1">回溯 <a class="header-anchor" href="#回溯" aria-label="Permalink to &quot;回溯&quot;">​</a></h3><blockquote><p>backtracking</p></blockquote><p>候选解数量大，NP-复杂问题</p><p>把解空间组织成树结构然后进行搜索</p><p>回溯步骤:</p><ol><li>定义一个解空间，它包含问题的解。</li><li>利用适于搜索的方法组织解空间。</li><li>利用深度优先法搜索解空间。</li></ol><p>回溯法采用试错的思想，它尝试分步的去解决一个问题。在分步解决问题的过程中，当它通过尝试发现，现有的分步答案不能得到有效的正确的解答的时候，它将取消上一步甚至是上几步的计算，再通过其它的可能的分步解答再次尝试寻找问题的答案。回溯法通常用最简单的递归方法来实现，在反复重复上述的步骤后可能出现两种情况：</p><p>找到一个可能存在的正确的答案 在尝试了所有可能的分步方法后宣告该问题没有答案 在最坏的情况下，回溯法会导致一次复杂度为指数时间的计算。</p><p>全局维护一个状态，状态重置</p><h3 id="分支定界" tabindex="-1">分支定界 <a class="header-anchor" href="#分支定界" aria-label="Permalink to &quot;分支定界&quot;">​</a></h3><blockquote><p>branch and bound</p></blockquote><h3 id="动态规划" tabindex="-1">动态规划 <a class="header-anchor" href="#动态规划" aria-label="Permalink to &quot;动态规划&quot;">​</a></h3><h3 id="压缩" tabindex="-1"><a href="./compress.html">压缩</a> <a class="header-anchor" href="#压缩" aria-label="Permalink to &quot;[压缩](./compress.md)&quot;">​</a></h3><h2 id="编程技巧" tabindex="-1">编程技巧 <a class="header-anchor" href="#编程技巧" aria-label="Permalink to &quot;编程技巧&quot;">​</a></h2><h3 id="前缀和" tabindex="-1">前缀和 <a class="header-anchor" href="#前缀和" aria-label="Permalink to &quot;前缀和&quot;">​</a></h3><p>数列的前n项的和，是一种重要的预处理方式，能大大降低查询的时间复杂度。</p><h3 id="递归" tabindex="-1"><a href="./recursion.html">递归</a> <a class="header-anchor" href="#递归" aria-label="Permalink to &quot;[递归](./recursion.md)&quot;">​</a></h3><p>许多著名的算法都离不开递归，如回溯算法，快速排序算法，分而治之算法，深度优先搜索算法等</p><p><a href="https://zhuanlan.zhihu.com/p/428479862" target="_blank" rel="noreferrer">95% 的算法都是基于这 6 种算法思想 - 知乎</a><a href="https://zhuanlan.zhihu.com/p/396686678" target="_blank" rel="noreferrer">《剑指 Offer》作者是如何看待题海战术的？ - 知乎</a></p><p><a href="https://visualgo.net/zh" target="_blank" rel="noreferrer">VisuAlgo - 数据结构和算法动态可视化 (Chinese)</a></p><h3 id="跳指针问题" tabindex="-1">跳指针问题 <a class="header-anchor" href="#跳指针问题" aria-label="Permalink to &quot;跳指针问题&quot;">​</a></h3><p>比如要求原地修改数组</p><ol><li>倒序</li><li>快慢指针</li></ol><h2 id="复杂度" tabindex="-1">复杂度 <a class="header-anchor" href="#复杂度" aria-label="Permalink to &quot;复杂度&quot;">​</a></h2><p><img src="https://i.stack.imgur.com/jIGhf.png" alt="jIGhf.png (835×579)"><a href="https://stackoverflow.com/questions/2307283/what-does-olog-n-mean-exactly" target="_blank" rel="noreferrer">algorithm - What does O(log n) mean exactly? - Stack Overflow</a></p><ul><li>评估算法优劣，反映运行时间或占用存储空间随输入规模增长而增长的量级</li><li>空间复杂度： 衡量运行时存储空间的占用，一般用大写 S(pace) <ul><li>内存有限制，需要选择更少内存方案</li><li>评估能解决多大规模问题</li></ul></li><li>时间复杂度： 定性描述算法运行时间的函数，一般用大写 O(peration) - 时间限制，避免陷入死循环 - 需要实时响应 <a href="https://blog.csdn.net/zolalad/article/details/11848739" target="_blank" rel="noreferrer">算法的时间复杂度和空间复杂度-总结 - CSDN 博客</a><a href="https://juejin.im/post/5c174198f265da611036f4ea" target="_blank" rel="noreferrer">冰与火之歌：「时间」与「空间」复杂度 - 掘金</a></li></ul><h3 id="程序性能" tabindex="-1">程序性能 <a class="header-anchor" href="#程序性能" aria-label="Permalink to &quot;程序性能&quot;">​</a></h3><ul><li>用操作数和执行步数来估计程序的运行时间。用符号法来分别描述程序在最好、最坏和平均情况下的运行时间。</li><li>程序性能指需要内存和时间的多少</li><li>两种分析方法：分析和测量（实验）</li><li>实例特征，包含着可以决定程序空间大小的因素（如，输入和输出的数量或相关数的大小）。例如，对 n 个元素排序的程序，它所需要的空间大小是 n 的函数，n 为其实例特征。</li><li>相对来说，指令空间的大小受实例特征的影响不大。常量及简单变量所需要的空间与实例特征也没有多大关系，除非相关数的规模对于选定的数据类型来说实在太大。一些动态分配空间也可以不依赖实例特征。环境栈的大小一般不依赖实例特征，除非使用了递归函数。当使用递归函数时，实例特征通常影响（但不总是）环境栈的大小。</li><li>递归函数所需要的栈空间通常称为递归栈空间。它的大小依赖于局部变量和形式参数所需要的空间，依赖于递归的最大深度和编译器。</li></ul><h3 id="big-o-notation" tabindex="-1">Big O notation <a class="header-anchor" href="#big-o-notation" aria-label="Permalink to &quot;Big O notation&quot;">​</a></h3><table><thead><tr><th>符号</th><th>数学描述</th></tr></thead><tbody><tr><td>O(1)</td><td>常数</td></tr><tr><td>O(log n)</td><td>对数</td></tr><tr><td>O(n)</td><td>线性</td></tr><tr><td>O(n^2)</td><td>平方</td></tr><tr><td>O(n^3)</td><td>立方</td></tr><tr><td>O(2^n)</td><td>指数</td></tr><tr><td>O(n!)</td><td>阶乘</td></tr></tbody></table><p>有多个复杂度时，只看最高复杂度</p><table><thead><tr><th>算法</th><th>复杂度</th></tr></thead><tbody><tr><td>递归</td><td>O(2^n)</td></tr><tr><td>二分</td><td>O(log n)</td></tr><tr><td>二叉树遍历</td><td>O(n)</td></tr><tr><td>优化排序矩阵查找</td><td>O(n)</td></tr><tr><td>归并、快排</td><td>O(n log n)</td></tr></tbody></table><p><a href="https://en.wikipedia.org/wiki/Master_theorem_analysis_of_algorithms" target="_blank" rel="noreferrer">Master theorem (analysis of algorithms) - Wikipedia</a></p><p><code>O(n log n)</code> 念什么？</p><p><code>2^n</code>和<code>n^2</code>，谁大，指数 n &gt; 2，随着 n 变大，前者会远大于后者</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>2 ** 10 = 1024</span></span>
<span class="line"><span>10 * 10 = 100</span></span></code></pre></div><p>array 转 set，需要遍历，时间复杂度 O(n) <a href="https://stackoverflow.com/questions/63543514/time-complexity-big-o-of-converting-an-array-to-a-set" target="_blank" rel="noreferrer">javascript - Time complexity (Big-O) of converting an array to a Set - Stack Overflow</a></p><p><a href="https://oi-wiki.org/" target="_blank" rel="noreferrer">oi-wiki.org - 编程竞赛知识库</a></p><p><a href="https://github.com/changgyhub/leetcode_101" target="_blank" rel="noreferrer">changgyhub/leetcode_101: LeetCode 101：和你一起你轻松刷题（C++）</a></p><h2 id="前端应用" tabindex="-1">前端应用 <a class="header-anchor" href="#前端应用" aria-label="Permalink to &quot;前端应用&quot;">​</a></h2><ul><li>你熟知的 DOM 树、AST 树、以及 Vue、React 的 Virtual DOM 都是树。</li><li>React Hooks 的本质是数组，React Fiber 是基于链表实现的。</li><li>HTTP 缓存响应消息 和 Vue 的 keep-alive 都用到了 LRU 算法。</li><li>浏览器前进后退功能通过栈实现。</li><li>TCP 连接实现多路复用时借助了epoll，而决定 epoll 高效的原因：数据结构采用了红黑树和队列。</li></ul>`,55),o=[i];function n(h,d,p,s,c,u){return e(),t("div",null,o)}const g=a(l,[["render",n]]);export{f as __pageData,g as default};
